const quizBank = [{"id": 1, "question": "Seorang perempuan berusia 27 tahun datang dengan keluhan nyeri saat buang air kecil dan sering berkemih sejak 2 hari lalu. Demam dan nyeri pinggang disangkal. Pada pemeriksaan fisik didapatkan nyeri tekan suprapubik tanpa nyeri ketok kostovertebra. Urinalisis menunjukkan leukosit esterase positif dan nitrit positif. Apakah tata laksana lini pertama yang paling tepat?", "options": ["Siprofloksasin 2 × 500 mg selama 14 hari", "Nitrofurantoin 2 × 100 mg selama 5 hari", "Seftriakson 1 gram intravena dosis tunggal", "Amoksisilin 3 × 500 mg selama 3 hari", "Gentamisin 80 mg intramuskular selama 7 hari"], "answer": 1, "topic": "ISK, pielonefritis & IMS"}, {"id": 2, "question": "Seorang perempuan hamil usia gestasi 16 minggu datang untuk kontrol rutin tanpa keluhan berkemih. Hasil kultur urin rutin menunjukkan pertumbuhan Escherichia coli lebih dari 105 CFU/mL. Apakah tindakan klinis yang paling tepat dilakukan dokter?", "options": ["Observasi tanpa antibiotik karena pasien asimtomatik", "Memberikan terapi sefaleksin oral selama 5–7 hari", "Memberikan siprofloksasin dosis tunggal", "Memberikan doksisiklin 2 × 100 mg selama 7 hari", "Merujuk pasien ke dokter spesialis urologi"], "answer": 1, "topic": "ISK, pielonefritis & IMS"}, {"id": 3, "question": "Seorang perempuan berusia 24 tahun mengeluh demam menggigil, mual, dan nyeri pinggang kanan sejak 2 hari lalu, didahului nyeri saat berkemih. Suhu tubuh 38,9°C, terdapat nyeri ketok sudut kostovertebra kanan. Tidak ada tanda sepsis maupun muntah persisten. Apakah diagnosis yang paling tepat?", "options": ["Sistitis akut tanpa komplikasi", "Pielonefritis akut tanpa komplikasi", "Glomerulonefritis akut pascastreptokokus", "Ureterolitiasis proksimal kanan", "Apendisitis akut retrosekal"], "answer": 1, "topic": "ISK, pielonefritis & IMS"}, {"id": 4, "question": "Pada pasien perempuan dengan pielonefritis akut tanpa komplikasi yang masih mampu menerima asupan per oral dengan baik, antibiotik empiris rawat jalan yang sesuai standar pelayanan primer adalah:", "options": ["Siprofloksasin 2 × 500 mg per oral selama 7 hari", "Fosfomisin 3 gram dosis tunggal", "Nitrofurantoin 2 × 100 mg selama 5 hari", "Metronidazol 3 × 500 mg selama 7 hari", "Asiklovir 5 × 400 mg selama 7 hari"], "answer": 0, "topic": "ISK, pielonefritis & IMS"}, {"id": 5, "question": "Seorang laki-laki berusia 25 tahun mengeluh keluar cairan kental berwarna kuning kehijauan dari ujung penis disertai rasa perih saat berkemih sejak 3 hari lalu. Riwayat kontak seksual berisiko 5 hari sebelumnya. Pada pewarnaan Gram sekret uretra ditemukan diplokokus Gram-negatif intraseluler. Apakah regimen terapi yang paling tepat?", "options": ["Sefiksim 400 mg dosis tunggal + Doksisiklin 2 × 100 mg selama 7 hari", "Benzatin penisilin G 2,4 juta IU intramuskular dosis tunggal", "Metronidazol 2 gram per oral dosis tunggal", "Asiklovir 3 × 400 mg per oral selama 7 hari", "Ketokonazol 1 × 200 mg per oral selama 7 hari"], "answer": 0, "topic": "ISK, pielonefritis & IMS"}, {"id": 6, "question": "Alasan utama pemberian doksisiklin atau azitromisin secara bersamaan pada pasien yang terdiagnosis uretritis gonore adalah:", "options": ["Mencegah resistensi terhadap sefalosporin generasi ketiga", "Mengatasi koinfeksi Chlamydia trachomatis yang sering menyertai", "Mengurangi nyeri disuria secara cepat", "Mencegah terjadinya striktura uretra pascainfeksi", "Mengobati infeksi jamur sekunder pada glans penis"], "answer": 1, "topic": "ISK, pielonefritis & IMS"}, {"id": 7, "question": "Seorang laki-laki berusia 29 tahun datang dengan keluhan luka nyeri pada batang penis sejak 4 hari lalu. Pada pemeriksaan tampak ulkus multipel berdiameter 1 cm dengan dasar kotor, tepi tidak rata, bergaung, mudah berdarah, serta limfadenopati inguinal unilateral yang nyeri. Apakah diagnosis yang paling mungkin?", "options": ["Sifilis primer (ulcus durum)", "Chancroid (ulcus molle)", "Herpes genitalis rekuren", "Limfogranuloma venereum", "Granuloma inguinale"], "answer": 1, "topic": "ISK, pielonefritis & IMS"}, {"id": 8, "question": "Etiologi bakteri penyebab penyakit chancroid adalah:", "options": ["Treponema pallidum", "Neisseria gonorrhoeae", "Haemophilus ducreyi", "Klebsiella granulomatis", "Mycoplasma genitalium"], "answer": 2, "topic": "ISK, pielonefritis & IMS"}, {"id": 9, "question": "Terapi lini pertama yang direkomendasikan untuk pasien dengan chancroid sesuai kompetensi tingkat 3A adalah:", "options": ["Azitromisin 1 gram per oral dosis tunggal", "Valasiklovir 2 × 500 mg selama 5 hari", "Flukonazol 150 mg dosis tunggal", "Gentamisin 5 mg/kgBB intravena", "Tinidazol 2 gram dosis tunggal"], "answer": 0, "topic": "ISK, pielonefritis & IMS"}, {"id": 10, "question": "Seorang laki-laki berusia 42 tahun mengeluh demam menggigil, nyeri perineum, disuria, dan frekuensi berkemih meningkat sejak 3 hari lalu. Pada pemeriksaan colok dubur teraba prostat membengkak, hangat, dan sangat nyeri tekan. Tindakan apa yang harus dihindari pada pasien ini?", "options": ["Pemberian antibiotik fluorokuinolon", "Pemijatan prostat (prostatic massage)", "Pemeriksaan kultur urin porsi tengah", "Pemberian antipiretik dan analgesik", "Pemasangan kateter suprapubik bila terjadi retensi urin berat"], "answer": 1, "topic": "ISK, pielonefritis & IMS"}, {"id": 11, "question": "Seorang laki-laki berusia 22 tahun mengeluh nyeri skrotum kanan yang timbul bertahap sejak 3 hari lalu disertai demam ringan dan disuria. Pada pemeriksaan fisik didapatkan skrotum kanan bengkak, hiperemis, refleks kremaster positif, dan nyeri berkurang saat skrotum diangkat ke atas. Apakah diagnosis yang paling tepat?", "options": ["Torsio testis", "Epididimitis akut", "Varikokel derajat III", "Hidrokel komunikan", "Hernia inguinalis inkarserata"], "answer": 1, "topic": "ISK, pielonefritis & IMS"}, {"id": 12, "question": "Pada pria berusia di bawah 35 tahun yang aktif secara seksual, patogen tersering penyebab epididimitis akut adalah:", "options": ["Pseudomonas aeruginosa dan Enterococcus faecalis", "Chlamydia trachomatis dan Neisseria gonorrhoeae", "Staphylococcus saprophyticus dan Proteus mirabilis", "Mycobacterium tuberculosis dan Candida albicans", "Streptococcus pyogenes dan Klebsiella pneumoniae"], "answer": 1, "topic": "ISK, pielonefritis & IMS"}, {"id": 13, "question": "Seorang anak laki-laki berusia 4 tahun dibawa ibunya karena ujung kulup penis menggembung saat buang air kecil. Pada pemeriksaan tampak preputium tidak dapat ditarik ke belakang melewati glans penis tanpa tanda peradangan akut maupun cincin konstriksi. Apakah diagnosis dan tingkat kompetensinya?", "options": ["Parafimosis – tingkat kemampuan 4A", "Fimosis – tingkat kemampuan 4A", "Hipospadia – tingkat kemampuan 2", "Epispadia – tingkat kemampuan 2", "Balanitis xerotica obliterans – tingkat kemampuan 3B"], "answer": 1, "topic": "ISK, pielonefritis & IMS"}, {"id": 14, "question": "Seorang anak laki-laki berusia 7 tahun dibawa ke IGD karena nyeri hebat pada ujung penis setelah bermain menarik kulit kulupnya 3 jam lalu. Tampak preputium retraksi di belakang sulkus koronarius membentuk cincin konstriksi yang menjepit glans penis hingga tampak edematosa dan kebiruan. Apakah tindakan awal yang paling tepat?", "options": ["Memberikan salep kortikosteroid dan menyuruh pulang", "Kompres dingin/manitol untuk mengurangi edema lalu reduksi manual", "Pemasangan kateter uretra ukuran besar segera", "Observasi selama 24 jam dengan pemberian antibiotik oral", "Insisi vertikal pada bagian ventral penis"], "answer": 1, "topic": "ISK, pielonefritis & IMS"}, {"id": 15, "question": "Mikroorganisme yang bertanggung jawab atas lebih dari 80% kasus infeksi saluran kemih tanpa komplikasi di komunitas adalah:", "options": ["Proteus mirabilis", "Klebsiella pneumoniae", "Escherichia coli", "Pseudomonas aeruginosa", "Staphylococcus aureus"], "answer": 2, "topic": "ISK, pielonefritis & IMS"}, {"id": 16, "question": "Pemeriksaan nitrit pada dipstik urin bernilai positif pada infeksi saluran kemih karena sebagian besar bakteri Gram-negatif saluran kemih mampu mengubah:", "options": ["Nitrat menjadi nitrit", "Urea menjadi amonia", "Bilirubin menjadi urobilinogen", "Glukosa menjadi asam laktat", "Kreatinin menjadi kreatin"], "answer": 0, "topic": "ISK, pielonefritis & IMS"}, {"id": 17, "question": "Seorang perempuan berusia 30 tahun dengan pielonefritis akut tanpa komplikasi mendapat terapi siprofloksasin oral. Kapan pasien harus segera dievaluasi ulang untuk kemungkinan rujukan ke rumah sakit?", "options": ["Jika urin masih berwarna kuning pekat setelah 6 jam", "Jika demam dan nyeri pinggang tidak membaik setelah 48–72 jam terapi", "Jika frekuensi berkemih berkurang pada hari kedua", "Jika hasil urinalisis kontrol hari pertama masih menunjukkan leukosituria", "Jika nafsu makan baru membaik pada hari ketiga"], "answer": 1, "topic": "ISK, pielonefritis & IMS"}, {"id": 18, "question": "Seorang perempuan berusia 35 tahun menderita gonore anogenital tanpa komplikasi dan memiliki riwayat alergi berat terhadap golongan sefalosporin. Regimen alternatif yang direkomendasikan adalah:", "options": ["Gentamisin 240 mg IM dosis tunggal + Azitromisin 2 gram oral dosis tunggal", "Amoksisilin 500 mg oral dosis tunggal", "Metronidazol 500 mg oral selama 5 hari", "Kotrimoksazol 960 mg oral dosis tunggal", "Eritromisin 250 mg oral selama 3 hari"], "answer": 0, "topic": "ISK, pielonefritis & IMS"}, {"id": 19, "question": "Perbedaan karakteristik ulkus pada chancroid dibandingkan dengan ulkus durum pada sifilis primer adalah:", "options": ["Ulkus chancroid soliter, indurasi keras, dan tidak nyeri", "Ulkus chancroid multipel, dasar kotor purulen, tepi bergaung, dan sangat nyeri", "Ulkus chancroid diawali vesikel berkelompok yang dangkal", "Ulkus chancroid selalu disertai pembesaran kelenjar getah bening tidak nyeri", "Ulkus chancroid sembuh spontan dalam 24 jam tanpa jaringan parut"], "answer": 1, "topic": "ISK, pielonefritis & IMS"}, {"id": 20, "question": "Tanda pemeriksaan fisik berupa hilangnya rasa nyeri pada skrotum ketika testis diangkat ke arah simfisis pubis pada pasien epididimitis disebut sebagai:", "options": ["Tanda Prehn positif (Prehn's sign)", "Tanda Blue Dot positif", "Tanda Phrenic positif", "Tanda Chvostek positif", "Tanda Rovsing positif"], "answer": 0, "topic": "ISK, pielonefritis & IMS"}, {"id": 21, "question": "Seorang anak laki-laki berusia 8 tahun dibawa ke puskesmas dengan keluhan wajah sembab terutama saat bangun tidur dan urin berwarna merah kecokelatan seperti air cucian daging sejak 2 hari lalu. Dua minggu sebelumnya pasien mengalami sakit tenggorokan. Tekanan darah 145/95 mmHg. Urinalisis menunjukkan hematuria dan silinder eritrosit. Apakah diagnosis yang paling tepat?", "options": ["Sindroma nefrotik", "Glomerulonefritis akut pascastreptokokus", "Pielonefritis akut", "Nefrolitiasis", "Nekrosis tubular akut"], "answer": 1, "topic": "Glomerulus & fungsi ginjal"}, {"id": 22, "question": "Pada pasien dengan glomerulonefritis akut pascastreptokokus (tingkat kemampuan 3A), pemeriksaan serologi yang paling mendukung bukti infeksi streptokokus sebelumnya adalah:", "options": ["Peningkatan titer ASO (Antistreptolysin O) dan penurunan komplemen C3", "Peningkatan komplemen C3 dan C4 secara bermakna", "ANA test positif dengan pola homogen", "Peningkatan kadar IgE serum total", "Penurunan kadar kreatinin serum di bawah normal"], "answer": 0, "topic": "Glomerulus & fungsi ginjal"}, {"id": 23, "question": "Tata laksana awal di layanan primer pada anak dengan glomerulonefritis akut tanpa komplikasi berat meliputi:", "options": ["Tirah baring, restriksi garam dan cairan, serta diuretik furosemid bila ada edema/hipertensi", "Pemberian kortikosteroid dosis tinggi selama 8 minggu", "Hidrasi cairan intravena 3 liter per hari secara agresif", "Pemberian antibiotik siprofloksasin jangka panjang", "Tindakan hemodialisis cito pada semua pasien"], "answer": 0, "topic": "Glomerulus & fungsi ginjal"}, {"id": 24, "question": "Seorang anak perempuan berusia 6 tahun dibawa dengan keluhan bengkak seluruh tubuh sejak 1 minggu lalu. Pemeriksaan laboratorium menunjukkan proteinuria masif (+4), hipoalbuminemia (1,8 g/dL), dan hiperkolesterolemia (340 mg/dL). Apakah diagnosis yang paling tepat?", "options": ["Glomerulonefritis akut", "Sindroma nefrotik", "Penyakit ginjal kronik stadium 5", "Gagal jantung kongestif", "Sirosis hepatis dekompensata"], "answer": 1, "topic": "Glomerulus & fungsi ginjal"}, {"id": 25, "question": "Trias klasik yang ditambah hiperkolesterolemia dan lipiduria merupakan ciri khas dari sindroma nefrotik. Tiga komponen utama tersebut adalah:", "options": ["Hematuria, hipertensi, dan azotemia", "Proteinuria masif, hipoalbuminemia, dan edema anasarka", "Oliguria, hiperkalemia, dan asidosis metabolik", "Demam, nyeri pinggang, dan piuria", "Poliuria, polidipsia, dan hiperglikemia"], "answer": 1, "topic": "Glomerulus & fungsi ginjal"}, {"id": 26, "question": "Penyebab tersering sindroma nefrotik idiopatik pada anak-anak adalah:", "options": ["Nefropati membranosa", "Minimal change disease (kelainan minimal)", "Glomerulosklerosis fokal segmental", "Nefropati IgA", "Glomerulonefritis membranoproliferatif"], "answer": 1, "topic": "Glomerulus & fungsi ginjal"}, {"id": 27, "question": "Seorang laki-laki berusia 58 tahun dirawat pascaoperasi besar dengan perdarahan masif dan hipotensi berkepanjangan. Produksi urin menurun menjadi 150 mL dalam 24 jam, dan kreatinin serum meningkat dari 1,0 mg/dL menjadi 2,8 mg/dL dalam 48 jam. Kriteria KDIGO untuk Acute Kidney Injury (AKI) terpenuhi apabila:", "options": ["Kreatinin serum meningkat ≥ 0,3 mg/dL dalam 48 jam atau ≥ 1,5 kali nilai dasar dalam 7 hari", "Kreatinin serum meningkat ≥ 0,1 mg/dL dalam 1 bulan", "Laju filtrasi glomerulus menurun di bawah 90 mL/menit selama 6 bulan", "Volume urin kurang dari 1.000 mL dalam 24 jam", "Terdapat mikroalbuminuria persisten selama 3 bulan"], "answer": 0, "topic": "Glomerulus & fungsi ginjal"}, {"id": 28, "question": "Seorang pasien mengalami dehidrasi berat akibat diare profus disertai penurunan produksi urin. Pada pemeriksaan urin didapatkan osmolalitas urin > 500 mOsm/kg, natrium urin < 20 mEq/L, dan fraksi ekskresi natrium (FENa) < 1%. Klasifikasi AKI pada pasien ini adalah:", "options": ["AKI prerenal", "AKI renal (intrinsik)", "AKI postrenal", "Penyakit ginjal kronik eksaserbasi akut", "Nefritis interstisial akut"], "answer": 0, "topic": "Glomerulus & fungsi ginjal"}, {"id": 29, "question": "Seorang laki-laki berusia 50 tahun menjalani pemeriksaan CT-scan dengan kontras intravena dan mengonsumsi aminoglikosida dosis tinggi. Tiga hari kemudian terjadi oliguria dan peningkatan kreatinin serum. Pemeriksaan sedimen urin menunjukkan silinder granular kecokelatan (muddy brown granular casts) dan FENa > 2%. Apakah diagnosis yang paling tepat?", "options": ["Nekrosis tubular akut (ATN)", "Azotemia prerenal", "Glomerulonefritis kresentik", "Uropati obstruktif bilateral", "Sindroma hepatorenal"], "answer": 0, "topic": "Glomerulus & fungsi ginjal"}, {"id": 30, "question": "Temuan mikroskopis sedimen urin yang paling khas pada nekrosis tubular akut adalah:", "options": ["Silinder eritrosit (red blood cell casts)", "Silinder granular kecokelatan keruh (muddy brown casts) dan sel epitel tubulus", "Silinder leukosit (white blood cell casts)", "Kristal asam urat berbentuk belah ketupat", "Silinder hialin jernih"], "answer": 1, "topic": "Glomerulus & fungsi ginjal"}, {"id": 31, "question": "Seorang perempuan berusia 62 tahun dengan riwayat diabetes melitus dan hipertensi tidak terkontrol mengeluh lemas, mual, pucat, dan gatal-gatal pada kulit. Hasil laboratorium: Hb 8,2 g/dL, ureum 165 mg/dL, kreatinin 6,4 mg/dL dengan estimasi LFG 8 mL/menit/1,73 m2 selama lebih dari 4 bulan. Termasuk stadium berapakah Penyakit Ginjal Kronik (PGK) pasien ini?", "options": ["PGK stadium 2", "PGK stadium 3a", "PGK stadium 3b", "PGK stadium 4", "PGK stadium 5"], "answer": 4, "topic": "Glomerulus & fungsi ginjal"}, {"id": 32, "question": "Penyebab utama terjadinya anemia normositik normokrom pada pasien penyakit ginjal kronik adalah:", "options": ["Defisiensi sintesis hormon eritropoietin oleh ginjal", "Hemolisis intravaskular akibat hipertensi", "Defisiensi vitamin B12 akibat diet rendah protein", "Perdarahan saluran kemih kronik", "Hipersplenisme sekunder"], "answer": 0, "topic": "Glomerulus & fungsi ginjal"}, {"id": 33, "question": "Berikut ini merupakan indikasi mutlak dilakukannya terapi pengganti ginjal (hemodialisis) segera pada pasien AKI atau PGK, kecuali:", "options": ["Asidosis metabolik berat yang refrakter terhadap terapi bikarbonat", "Hiperkalemia berat disertai perubahan gelombang EKG", "Edema paru akut yang tidak responsif terhadap diuretik", "Ensefalopati uremikum atau perikarditis uremikum", "Peningkatan kreatinin ringan tanpa gejala klinis maupun gangguan elektrolit"], "answer": 4, "topic": "Glomerulus & fungsi ginjal"}, {"id": 34, "question": "Tingkat kemampuan dokter umum dalam standar kompetensi untuk menangani pasien dengan Acute Kidney Injury (AKI), Penyakit Ginjal Kronik, Sindroma Nefrotik, dan Nekrosis Tubular Akut adalah:", "options": ["Tingkat kemampuan 1", "Tingkat kemampuan 2", "Tingkat kemampuan 3A", "Tingkat kemampuan 3B", "Tingkat kemampuan 4A"], "answer": 1, "topic": "Glomerulus & fungsi ginjal"}, {"id": 35, "question": "Seorang pasien PGK stadium 4 mengalami hiperfosfatemia dan hipokalsemia yang memicu peningkatan hormon paratiroid. Komplikasi metabolik yang terjadi pada kondisi ini adalah:", "options": ["Hiperparatiroidisme sekunder dan osteodistrofi ginjal", "Hipoparatiroidisme primer", "Diabetes insipidus nefrogenik", "Sindroma Fanconi", "Alkalosis respiratorik kronik"], "answer": 0, "topic": "Glomerulus & fungsi ginjal"}, {"id": 36, "question": "Fase pemulihan (recovery phase) pada nekrosis tubular akut ditandai oleh munculnya gejala klinis berupa:", "options": ["Poliuria akibat regenerasi sel tubulus yang belum mampu memekatkan urin secara optimal", "Anuria total yang menetap selama beberapa minggu", "Hematuria makroskopik masif", "Hipertensi maligna", "Proteinuria nefrotik"], "answer": 0, "topic": "Glomerulus & fungsi ginjal"}, {"id": 37, "question": "Pada pasien sindroma nefrotik, hilangnya protein antitrombin III melalui urin menyebabkan peningkatan risiko terjadinya:", "options": ["Keadaan hiperkoagulabilitas dan trombosis vena renalis", "Perdarahan intrakranial spontan", "Hipoglikemia berat", "Hipernatremia berat", "Alkalosis metabolik"], "answer": 0, "topic": "Glomerulus & fungsi ginjal"}, {"id": 38, "question": "Pemeriksaan ultrasonografi ginjal pada pasien penyakit ginjal kronik lanjut umumnya menunjukkan gambaran:", "options": ["Ukuran kedua ginjal mengecil (kontraksi) dengan peningkatan ekogenisitas korteks dan batas kortikomeduler kabur", "Ukuran ginjal membesar simetris dengan batas kortikomeduler sangat tajam", "Dilatasi pelviokalises masif tanpa penipisan korteks", "Massa tunggal berbatas tegas di kutub atas ginjal", "Gambaran ginjal menyatu pada kutub bawah"], "answer": 0, "topic": "Glomerulus & fungsi ginjal"}, {"id": 39, "question": "Golongan obat antihipertensi yang menjadi pilihan utama untuk memperlambat progresivitas penyakit ginjal kronik dengan proteinuria adalah:", "options": ["Penghambat ACE (ACE inhibitor) atau ARB", "Penghambat kanal kalsium dihidropiridin", "Penyekat beta nonselektif", "Agonis alfa-2 sentral", "Vasodilator langsung hidralazin"], "answer": 0, "topic": "Glomerulus & fungsi ginjal"}, {"id": 40, "question": "Seorang anak dengan glomerulonefritis akut pascastreptokokus mengalami sakit kepala hebat, muntah proyektil, penurunan kesadaran, dan tekanan darah 180/120 mmHg. Komplikasi akut yang sedang terjadi adalah:", "options": ["Ensefalopati hipertensif", "Meningitis bakterialis", "Trombosis sinus kavernosus", "Perdarahan subaraknoid", "Ketoasidosis diabetikum"], "answer": 0, "topic": "Glomerulus & fungsi ginjal"}, {"id": 41, "question": "Seorang laki-laki berusia 40 tahun datang ke IGD dengan keluhan nyeri pinggang kiri sangat hebat yang hilang timbul dan menjalar hingga ke selangkangan serta skrotum kiri sejak 3 jam lalu. Pasien tampak gelisah terus berganti posisi dan mual. Terdapat nyeri ketok kostovertebra kiri. Apakah diagnosis yang paling tepat?", "options": ["Kolik renal", "Batu saluran kemih tanpa kolik", "Pielonefritis akut", "Ruptur ginjal", "Kista ginjal sederhana"], "answer": 0, "topic": "Batu & kegawatdaruratan urologi"}, {"id": 42, "question": "Terapi farmakologis lini pertama untuk meredakan nyeri akut pada pasien kolik renal tanpa kontraindikasi gangguan fungsi ginjal maupun tukak lambung adalah:", "options": ["Ketorolak 30 mg intravena atau diklofenak 75 mg intramuskular", "Parasetamol 500 mg per oral", "Skopolamin butilbromida oral", "Alopurinol 300 mg per oral", "Tamsulosin 0,4 mg per oral saja tanpa analgesik"], "answer": 0, "topic": "Batu & kegawatdaruratan urologi"}, {"id": 43, "question": "Jenis batu saluran kemih yang paling sering ditemukan di populasi (sekitar 70–80% kasus) dan tampak radioopak pada foto polos abdomen adalah:", "options": ["Batu kalsium oksalat", "Batu asam urat", "Batu sistin", "Batu matriks", "Batu xantin"], "answer": 0, "topic": "Batu & kegawatdaruratan urologi"}, {"id": 44, "question": "Seorang perempuan berusia 48 tahun mengeluh rasa pegal tumpul di pinggang kanan sejak beberapa bulan tanpa serangan nyeri hebat. Urinalisis menunjukkan hematuria mikroskopik dan pH urin 8,0. Foto polos abdomen menunjukkan batu besar mengisi seluruh sistem pelviokalises kanan (staghorn stone). Apakah diagnosis yang paling sesuai?", "options": ["Batu saluran kemih tanpa kolik", "Kolik renal akut", "Karsinoma sel renal", "Ginjal polikistik", "Ginjal tapal kuda"], "answer": 0, "topic": "Batu & kegawatdaruratan urologi"}, {"id": 45, "question": "Batu saluran kemih jenis struvit (magnesium amonium fosfat) berkaitan erat dengan infeksi saluran kemih kronik oleh bakteri penghasil enzim urease, yaitu:", "options": ["Proteus mirabilis", "Escherichia coli", "Streptococcus agalactiae", "Neisseria gonorrhoeae", "Chlamydia trachomatis"], "answer": 0, "topic": "Batu & kegawatdaruratan urologi"}, {"id": 46, "question": "Seorang remaja laki-laki berusia 16 tahun datang ke IGD dengan keluhan nyeri skrotum kiri mendadak dan sangat hebat sejak 2 jam lalu saat sedang tidur. Pada pemeriksaan fisik tampak testis kiri terletak lebih tinggi dan melintang horizontal, bengkak, refleks kremaster kiri menghilang, dan nyeri tidak berkurang saat skrotum diangkat. Apakah diagnosis dan tingkat kompetensinya?", "options": ["Epididimitis akut – tingkat kemampuan 2", "Torsio testis – tingkat kemampuan 3B", "Varikokel – tingkat kemampuan 2", "Hidrokel – tingkat kemampuan 2", "Spermatokel – tingkat kemampuan 2"], "answer": 1, "topic": "Batu & kegawatdaruratan urologi"}, {"id": 47, "question": "Periode emas (golden period) untuk melakukan tindakan detorsi (pembedahan atau manual) agar viabilitas testis tetap terjaga pada kasus torsio testis adalah:", "options": ["Kurang dari 6 jam sejak awitan nyeri", "Antara 12 hingga 24 jam sejak awitan nyeri", "Antara 24 hingga 48 jam sejak awitan nyeri", "Maksimal 72 jam sejak awitan nyeri", "Setelah terapi antibiotik selama 5 hari"], "answer": 0, "topic": "Batu & kegawatdaruratan urologi"}, {"id": 48, "question": "Seorang laki-laki berusia 32 tahun mengalami kecelakaan jatuh terduduk mengenai palang besi (straddle injury). Pasien tidak dapat berkemih, tampak darah menetes dari meatus uretra eksterna, hematoma berbentuk kupu-kupu di perineum, dan pada pemeriksaan colok dubur prostat teraba melayang (high-riding prostate). Apakah diagnosis yang paling tepat?", "options": ["Ruptur uretra", "Ruptur ginjal", "Ruptur buli-buli intraperitoneal", "Striktura uretra", "Prostatitis akut"], "answer": 0, "topic": "Batu & kegawatdaruratan urologi"}, {"id": 49, "question": "Tindakan yang merupakan kontraindikasi absolut sebelum dilakukan pemeriksaan uretrografi retrograd pada pasien dengan kecurigaan ruptur uretra adalah:", "options": ["Pemasangan kateter uretra (kateter Foley transuretra)", "Pemeriksaan colok dubur", "Pemberian cairan infus kristaloid", "Pemberian analgesik intravena", "Rujukan segera ke spesialis urologi"], "answer": 0, "topic": "Batu & kegawatdaruratan urologi"}, {"id": 50, "question": "Apabila pasien dengan ruptur uretra mengalami retensi urin penuh dan nyeri hebat di IGD layanan primer sebelum dirujuk, tindakan diversi urin sementara yang aman dilakukan adalah:", "options": ["Sistostomi suprapubik (pungsi suprapubik)", "Pemasangan kateter Foley ukuran 18 Fr secara paksa", "Dilatasi uretra dengan busi logam", "Pemberian diuretik furosemid intravena", "Pemijatan daerah suprapubik"], "answer": 0, "topic": "Batu & kegawatdaruratan urologi"}, {"id": 51, "question": "Seorang laki-laki berusia 28 tahun dibawa ke IGD setelah mengalami benturan keras pada pinggang kanan akibat kecelakaan lalu lintas. Tanda vital stabil, terdapat jejas hematom di regio flank kanan dan hematuria makroskopik. Apakah diagnosis yang paling mungkin pada pasien ini?", "options": ["Ruptur ginjal", "Ruptur uretra", "Kolik renal", "Pielonefritis akut", "Torsio testis"], "answer": 0, "topic": "Batu & kegawatdaruratan urologi"}, {"id": 52, "question": "Pada pasien dengan kecurigaan trauma/ruptur ginjal yang hemodinamiknya stabil, pemeriksaan pencitraan baku emas untuk menentukan derajat cedera ginjal (klasifikasi AAST) adalah:", "options": ["CT-scan abdomen-pelvis dengan kontras intravena (fase ekskresi)", "Foto polos abdomen 3 posisi", "Uretrografi retrograd", "Sistografi retrograd", "MRI otak"], "answer": 0, "topic": "Batu & kegawatdaruratan urologi"}, {"id": 53, "question": "Seorang laki-laki berusia 34 tahun datang ke IGD karena penisnya terus ereksi kaku dan terasa sangat nyeri selama 6 jam tanpa disertai rangsangan seksual. Pasien memiliki riwayat mengonsumsi obat disfungsi ereksi secara berlebihan. Pada pemeriksaan tampak korpus kavernosum tegang keras sedangkan glans penis lunak. Apakah diagnosis yang paling tepat?", "options": ["Priapismus iskemik (low-flow priapism)", "Priapismus non-iskemik (high-flow priapism)", "Penyakit Peyronie", "Parafimosis", "Fraktur penis"], "answer": 0, "topic": "Batu & kegawatdaruratan urologi"}, {"id": 54, "question": "Tingkat kemampuan dokter umum untuk menangani kasus priapismus adalah tingkat kemampuan 3B. Apa risiko komplikasi permanen bila priapismus iskemik tidak ditangani segera?", "options": ["Fibrosis korpus kavernosum dan disfungsi ereksi permanen", "Infertilitas akibat nekrosis tubulus seminiferus", "Gagal ginjal akut postrenal", "Karsinoma sel skuamosa penis", "Ruptur kandung kemih"], "answer": 0, "topic": "Batu & kegawatdaruratan urologi"}, {"id": 55, "question": "Seorang laki-laki berusia 45 tahun mengeluh pancaran kencing melemah, terbelah (bercabang), dan harus mengejan sejak 6 bulan terakhir. Pasien memiliki riwayat infeksi gonore berulang dan pemasangan kateter urin lama 2 tahun lalu. Apakah diagnosis yang paling mungkin?", "options": ["Striktura uretra", "Torsio testis", "Priapismus", "Hidrokel", "Varikokel"], "answer": 0, "topic": "Batu & kegawatdaruratan urologi"}, {"id": 56, "question": "Pemeriksaan radiologi yang digunakan untuk memastikan lokasi dan panjang penyempitan lumen pada pasien striktura uretra adalah:", "options": ["Uretrografi retrograd dan uretrosistografi miksi", "Pielografi intravena (IVP)", "Ultrasonografi Doppler skrotum", "CT-scan kepala non-kontras", "Renogram isotop"], "answer": 0, "topic": "Batu & kegawatdaruratan urologi"}, {"id": 57, "question": "Batu ureter yang paling sering tersangkut secara anatomis berada pada tiga titik penyempitan ureter, yaitu:", "options": ["Ureteropelvic junction (UPJ), persilangan vasa iliaka, dan ureterovesical junction (UVJ)", "Kaliks minor, kaliks mayor, dan pelvis renalis", "Uretra pars prostatika, pars membranasea, dan pars spongiosa", "Trigonum vesika, fundus vesika, dan apeks vesika", "Piramida renalis, kolumna Bertin, dan korteks renalis"], "answer": 0, "topic": "Batu & kegawatdaruratan urologi"}, {"id": 58, "question": "Pada pasien dengan kolik renal akibat batu ureter distal berukuran < 5 mm tanpa tanda infeksi maupun obstruksi berat, terapi ekspulsif medikamentosa (MET) yang dapat diberikan untuk membantu pengeluaran batu adalah:", "options": ["Tamsulosin 0,4 mg sekali sehari (penyekat reseptor alfa-1)", "Propranolol 40 mg dua kali sehari", "Furosemid 40 mg tiga kali sehari", "Kaptopril 25 mg dua kali sehari", "Atropin sulfat 0,5 mg intravena"], "answer": 0, "topic": "Batu & kegawatdaruratan urologi"}, {"id": 59, "question": "Pasien dengan batu saluran kemih yang disertai demam tinggi menggigil (urosepsis) dan hidronefrosis obstruktif memerlukan tindakan segera berupa:", "options": ["Resusitasi cairan, antibiotik intravena, dan rujukan segera untuk dekompresi sistem pelviokalises", "Terapi ESWL (extracorporeal shock wave lithotripsy) segera saat sepsis", "Observasi rawat jalan dengan antipiretik oral", "Pemberian obat pelarut batu herbal selama 1 bulan", "Restriksi cairan total selama 48 jam"], "answer": 0, "topic": "Batu & kegawatdaruratan urologi"}, {"id": 60, "question": "Perbedaan klinis utama antara ruptur uretra anterior dan ruptur uretra posterior adalah:", "options": ["Ruptur uretra posterior sering berhubungan dengan fraktur tulang panggul dan high-riding prostate", "Ruptur uretra anterior selalu disebabkan oleh trauma tumpul kepala", "Ruptur uretra posterior tidak pernah menimbulkan retensi urin", "Ruptur uretra anterior tidak pernah menimbulkan hematoma perineum", "Ruptur uretra posterior dapat langsung dipasang kateter Foley tanpa pemeriksaan"], "answer": 0, "topic": "Batu & kegawatdaruratan urologi"}, {"id": 61, "question": "Seorang bayi laki-laki baru lahir diperiksa oleh dokter dan didapatkan muara uretra (meatus uretra eksterna) terletak di permukaan ventral (bagian bawah) batang penis disertai lengkungan penis ke arah ventral (chordee) dan preputium berlebih di sisi dorsal. Apakah diagnosis yang paling tepat?", "options": ["Hipospadia", "Epispadia", "Fimosis", "Parafimosis", "Striktura uretra"], "answer": 0, "topic": "Kongenital & skrotum-testis"}, {"id": 62, "question": "Tindakan medis yang harus dihindari pada bayi dengan diagnosis hipospadia sebelum dilakukan operasi rekonstruksi oleh dokter spesialis bedah/urologi adalah:", "options": ["Sirkumsisi (khitan), karena kulit preputium dibutuhkan untuk bahan rekonstruksi uretra", "Pemeriksaan ultrasonografi saluran kemih", "Rujukan ke dokter spesialis urologi/bedah anak", "Edukasi orang tua mengenai kondisi anatomis bayi", "Pemantauan pola berkemih bayi"], "answer": 0, "topic": "Kongenital & skrotum-testis"}, {"id": 63, "question": "Kelainan kongenital berupa letak meatus uretra eksterna yang berada di permukaan dorsal (bagian atas) penis dan sering berhubungan dengan ekstrofi kandung kemih disebut:", "options": ["Epispadia", "Hipospadia", "Kriptorkidismus", "Hidrokel", "Spermatokel"], "answer": 0, "topic": "Kongenital & skrotum-testis"}, {"id": 64, "question": "Seorang anak laki-laki berusia 1 tahun dibawa orang tuanya karena kantong skrotum kanan tampak kosong sejak lahir. Pada pemeriksaan teraba massa kecil di kanalis inguinalis kanan yang tidak dapat didorong masuk hingga ke dasar skrotum. Apakah diagnosis yang paling tepat?", "options": ["Kriptorkidismus (undescended testis)", "Retractile testis", "Hidrokel non-komunikan", "Varikokel", "Torsio testis"], "answer": 0, "topic": "Kongenital & skrotum-testis"}, {"id": 65, "question": "Perbedaan utama antara kriptorkidismus sejati dengan retractile testis pada pemeriksaan fisik adalah:", "options": ["Pada retractile testis, testis dapat ditarik ke dasar skrotum tanpa ketegangan dan tetap berada di sana sementara", "Pada retractile testis, testis tidak pernah teraba di mana pun meskipun dengan pemeriksaan ultrasonografi", "Pada kriptorkidismus, testis selalu turun saat anak mandi air hangat", "Retractile testis selalu memerlukan tindakan orkidopeksi cito sebelum usia 6 bulan", "Kriptorkidismus disebabkan oleh refleks kremaster yang terlalu lemah"], "answer": 0, "topic": "Kongenital & skrotum-testis"}, {"id": 66, "question": "Dua komplikasi jangka panjang utama dari kriptorkidismus yang tidak dikoreksi pada usia dini adalah:", "options": ["Infertilitas (gangguan spermatogenesis) dan peningkatan risiko keganasan testis (seminoma)", "Hipertensi renovaskular dan batu ginjal", "Priapismus dan striktura uretra", "Hiperplasia prostat jinak dan prostatitis", "Glomerulonefritis dan sindroma nefrotik"], "answer": 0, "topic": "Kongenital & skrotum-testis"}, {"id": 67, "question": "Seorang laki-laki berusia 26 tahun datang dengan keluhan rasa pegal berat di skrotum kiri terutama setelah berdiri lama dan belum memiliki keturunan setelah 2 tahun menikah. Pada pemeriksaan fisik tampak pelebaran pembuluh darah vena berkelok-kelok di atas testis kiri seperti \"kantung cacing\" (bag of worms) yang makin jelas saat manuver Valsalva. Apakah diagnosis yang paling tepat?", "options": ["Varikokel", "Hidrokel", "Spermatokel", "Epididimitis", "Seminoma"], "answer": 0, "topic": "Kongenital & skrotum-testis"}, {"id": 68, "question": "Varikokel jauh lebih sering terjadi pada sisi kiri dibandingkan sisi kanan karena alasan anatomis berupa:", "options": ["Vena spermatika interna kiri bermuara tegak lurus (90°) ke vena renalis kiri", "Testis kiri memiliki dua arteri testikularis", "Kanalis inguinalis kiri lebih lebar daripada kanan", "Vena spermatika interna kiri bermuara langsung ke vena kava inferior", "Refleks kremaster sisi kiri tidak ada secara fisiologis"], "answer": 0, "topic": "Kongenital & skrotum-testis"}, {"id": 69, "question": "Seorang laki-laki berusia 35 tahun mengeluh skrotum kanan membesar perlahan sejak 6 bulan lalu tanpa rasa nyeri. Pada palpasi teraba massa kistik kenyal, fluktuatif, testis kanan sulit diraba terpisah dari massa, dan uji transiluminasi menunjukkan cahaya menembus massa secara merata (transiluminasi positif). Apakah diagnosis yang paling tepat?", "options": ["Hidrokel", "Varikokel", "Seminoma", "Hernia inguinalis inkarserata", "Torsio testis"], "answer": 0, "topic": "Kongenital & skrotum-testis"}, {"id": 70, "question": "Seorang laki-laki berusia 40 tahun datang dengan keluhan benjolan kecil tidak nyeri di bagian atas testis kanan. Pada palpasi teraba massa kistik berbatas tegas yang terletak di kaput epididimis, terpisah dari testis, dan menunjukkan transiluminasi positif. Apakah diagnosis yang paling tepat?", "options": ["Spermatokel", "Hidrokel", "Varikokel", "Teratoma testis", "Epididimitis akut"], "answer": 0, "topic": "Kongenital & skrotum-testis"}, {"id": 71, "question": "Seorang pasien menjalani pemeriksaan ultrasonografi abdomen untuk keluhan nyeri perut nonspesifik dan secara kebetulan ditemukan kedua kutub bawah ginjal menyatu di garis tengah melewati depan aorta abdominalis (isthmus). Kelainan kongenital ini memiliki tingkat kemampuan 1 dan disebut:", "options": ["Ginjal tapal kuda (horseshoe kidney)", "Ginjal polikistik autosomal dominan", "Agenesis renal unilateral", "Ginjal ektopik pelvik", "Duplikasi ureter bilateral"], "answer": 0, "topic": "Kongenital & skrotum-testis"}, {"id": 72, "question": "Penyebab ginjal tapal kuda tidak dapat naik (ascent) mencapai posisi anatomis normal di fossa renalis selama perkembangan embriologis adalah tertahannya jembatan parenkim ginjal (isthmus) oleh:", "options": ["Pangkal arteri mesenterika inferior", "Trunkus seliakus", "Arteri iliaka eksterna", "Diafragma bagian posterior", "Ligamentum inguinale"], "answer": 0, "topic": "Kongenital & skrotum-testis"}, {"id": 73, "question": "Seorang laki-laki berusia 44 tahun mengeluh nyeri pinggang bilateral, hematuria, dan hipertensi. Ayahnya meninggal karena gagal ginjal di usia 50 tahun dan riwayat perdarahan subaraknoid. Pada palpasi abdomen teraba massa ginjal bilateral berbenjol-benjol besar. Apakah diagnosis yang paling tepat?", "options": ["Penyakit ginjal polikistik autosomal dominan (ginjal polikistik simtomatik)", "Ginjal tapal kuda", "Tumor Wilms", "Glomerulonefritis akut", "Sindroma nefrotik"], "answer": 0, "topic": "Kongenital & skrotum-testis"}, {"id": 74, "question": "Manifestasi ekstrarenal klasik yang sangat berkaitan dengan penyakit ginjal polikistik autosomal dominan dan perlu diwaspadai adalah:", "options": ["Aneurisma intrakranial (berry aneurysm) dan kista hepar", "Katarak kongenital dan tuli sensorineural", "Stenosis pilorus hipertrofik", "Tetralogi Fallot", "Fibrosis paru idiopatik"], "answer": 0, "topic": "Kongenital & skrotum-testis"}, {"id": 75, "question": "Apabila pada pemeriksaan fisik pasien laki-laki dewasa ditemukan varikokel sisi kanan yang muncul mendadak dan tidak mengempis saat pasien berbaring telentang, dokter harus mencurigai adanya:", "options": ["Massa retroperitoneal atau trombus tumor pada vena kava inferior/vena renalis", "Hidrokel komunikan kongenital", "Infeksi saluran kemih bawah", "Retractile testis fisiologis", "Fimosis derajat ringan"], "answer": 0, "topic": "Kongenital & skrotum-testis"}, {"id": 76, "question": "Seorang laki-laki berusia 60 tahun, perokok berat, datang dengan keluhan kencing berdarah (hematuria makroskopik) tanpa rasa nyeri sejak 1 bulan lalu, disertai nyeri pinggang kanan dan penurunan berat badan. Pada palpasi abdomen kanan teraba massa ginjal. Trias klasik hematuria, nyeri pinggang, dan massa abdomen merupakan ciri khas dari:", "options": ["Karsinoma sel renal", "Karsinoma prostat", "Hiperplasia prostat jinak", "Batu kandung kemih", "Prostatitis akut"], "answer": 0, "topic": "Neoplasma & prostat"}, {"id": 77, "question": "Seorang anak perempuan berusia 3 tahun dibawa ibunya karena perut kanan membesar sejak 2 bulan terakhir, teraba keras saat anak dimandikan. Pada pemeriksaan fisik teraba massa padat besar di regio flank kanan yang berbatas tegas dan tidak melewati garis tengah abdomen. Tekanan darah anak meningkat. Apakah diagnosis yang paling mungkin?", "options": ["Tumor Wilms (nefroblastoma)", "Neuroblastoma", "Ginjal tapal kuda", "Glomerulonefritis akut", "Hidrokel"], "answer": 0, "topic": "Neoplasma & prostat"}, {"id": 78, "question": "Karakteristik palpasi abdomen yang membedakan Tumor Wilms dari neuroblastoma pada anak adalah:", "options": ["Tumor Wilms memiliki permukaan licin dan jarang melewati garis tengah abdomen", "Tumor Wilms selalu melewati garis tengah dan disertai gerakan mata opsoklonus", "Tumor Wilms muncul setelah usia 20 tahun", "Tumor Wilms selalu disertai penurunan berat badan dalam 24 jam", "Tumor Wilms dapat dikempiskan dengan tekanan ringan"], "answer": 0, "topic": "Neoplasma & prostat"}, {"id": 79, "question": "Seorang laki-laki berusia 65 tahun, bekerja di pabrik pewarna tekstil dan perokok aktif selama 35 tahun, datang dengan keluhan hematuria makroskopik total tanpa disertai rasa nyeri (painless gross hematuria). Apakah diagnosis keganasan yang paling harus dicurigai?", "options": ["Karsinoma urotelial (karsinoma sel transisional kandung kemih)", "Seminoma testis", "Hiperplasia prostat jinak", "Epididimitis kronik", "Spermatokel"], "answer": 0, "topic": "Neoplasma & prostat"}, {"id": 80, "question": "Faktor risiko lingkungan dan pekerjaan yang paling kuat berhubungan dengan terjadinya karsinoma urotelial kandung kemih adalah:", "options": ["Merokok dan paparan senyawa amina aromatik (industri cat, karet, tekstil)", "Konsumsi makanan tinggi purin", "Paparan sinar ultraviolet berlebih", "Riwayat infeksi streptokokus tenggorokan", "Kurang asupan vitamin D"], "answer": 0, "topic": "Neoplasma & prostat"}, {"id": 81, "question": "Seorang laki-laki berusia 31 tahun datang dengan keluhan benjolan padat di testis kanan yang membesar perlahan sejak 4 bulan lalu tanpa rasa nyeri. Uji transiluminasi negatif. Hasil penanda tumor menunjukkan AFP (alpha-fetoprotein) normal dan beta-hCG sedikit meningkat. Apakah diagnosis keganasan testis tersering pada kelompok usia ini (tingkat kemampuan 1)?", "options": ["Seminoma", "Teratoma testis", "Hidrokel", "Varikokel", "Spermatokel"], "answer": 0, "topic": "Neoplasma & prostat"}, {"id": 82, "question": "Pernyataan yang benar mengenai penanda tumor serum pada keganasan testis adalah:", "options": ["Seminoma murni tidak pernah menghasilkan peningkatan kadar AFP (alpha-fetoprotein)", "Seminoma murni selalu menunjukkan peningkatan AFP di atas 1.000 ng/mL", "Penanda tumor dilakukan setelah biopsi insisi melalui kulit skrotum", "Peningkatan PSA adalah penanda spesifik untuk teratoma testis", "Penanda tumor testis tidak memiliki nilai dalam pemantauan pascaterapi"], "answer": 0, "topic": "Neoplasma & prostat"}, {"id": 83, "question": "Tumor sel germinal non-seminomatosa pada testis yang tersusun atas berbagai lapisan jaringan somatik matur maupun imatur (seperti tulang rawan, epitel, atau rambut) disebut:", "options": ["Teratoma testis", "Seminoma klasik", "Karsinoma sel renal", "Tumor Wilms", "Karsinoma urotelial"], "answer": 0, "topic": "Neoplasma & prostat"}, {"id": 84, "question": "Tindakan diagnostik yang dikontraindikasikan pada kecurigaan tumor ganas testis (seminoma maupun teratoma) karena risiko penyebaran sel tumor ke kelenjar getah bening inguinal adalah:", "options": ["Biopsi transkrotal (insisi/aspirasi jarum melewati kulit skrotum)", "Ultrasonografi skrotum", "Pemeriksaan penanda tumor AFP, beta-hCG, dan LDH", "Orkidektomi radikal melalui pendekatan inguinal", "Rontgen toraks dan CT-scan abdomen"], "answer": 0, "topic": "Neoplasma & prostat"}, {"id": 85, "question": "Seorang laki-laki berusia 68 tahun mengeluh sering terbangun malam hari untuk buang air kecil, pancaran urin melemah, harus menunggu sebelum urin keluar, dan terasa tidak lampias sejak 1 tahun terakhir. Pada pemeriksaan colok dubur teraba prostat membesar simetris, konsistensi kenyal, permukaan licin, sulkus medianus mendatar, dan kutub atas tidak teraba. Apakah diagnosis yang paling tepat?", "options": ["Hiperplasia prostat jinak (BPH)", "Karsinoma prostat", "Prostatitis bakterialis akut", "Striktura uretra", "Karsinoma urotelial"], "answer": 0, "topic": "Neoplasma & prostat"}, {"id": 86, "question": "Zona anatomis prostat yang paling sering mengalami pembesaran pada hiperplasia prostat jinak (BPH) sehingga menekan uretra pars prostatika adalah:", "options": ["Zona transisional", "Zona perifer", "Zona sentral", "Stroma fibromuskular anterior", "Kapsul prostat posterior"], "answer": 0, "topic": "Neoplasma & prostat"}, {"id": 87, "question": "Golongan obat yang bekerja merelaksasi otot polos leher kandung kemih dan prostat sehingga memperbaiki aliran urin secara cepat pada pasien BPH adalah:", "options": ["Penyekat reseptor alfa-1 adrenergik (seperti tamsulosin atau terazosin)", "Penghambat 5-alfa reduktase (seperti finasterid)", "Agonis reseptor muskarinik", "Diuretik hemat kalium", "Penghambat pompa proton"], "answer": 0, "topic": "Neoplasma & prostat"}, {"id": 88, "question": "Seorang laki-laki berusia 72 tahun mengeluh nyeri tulang punggung bawah dan panggul sejak 3 bulan lalu disertai gangguan berkemih. Pada pemeriksaan colok dubur teraba prostat berbenjol-benjol, konsistensi keras seperti batu (stony hard), asimetris, dan tidak nyeri tekan. Kadar PSA serum 48 ng/mL. Apakah diagnosis yang paling mungkin?", "options": ["Karsinoma prostat", "Hiperplasia prostat jinak", "Prostatitis akut", "Batu kandung kemih", "Ruptur uretra"], "answer": 0, "topic": "Neoplasma & prostat"}, {"id": 89, "question": "Lokasi tersering munculnya adenokarsinoma prostat dan lokasi tersering metastasis jauhnya berturut-turut adalah:", "options": ["Zona perifer prostat dan tulang (metastasis osteoblastik)", "Zona transisional prostat dan limpa", "Zona sentral prostat dan otot rangka", "Stroma anterior dan mukosa lambung", "Uretra pars spongiosa dan retina"], "answer": 0, "topic": "Neoplasma & prostat"}, {"id": 90, "question": "Bagaimana cara kerja penghambat enzim 5-alfa reduktase (finasterid/dutasterid) dalam tata laksana hiperplasia prostat jinak?", "options": ["Menghambat konversi testosteron menjadi dihidrotestosteron (DHT) sehingga mengecilkan volume prostat", "Merelaksasi otot polos sfingter uretra eksterna dalam 24 jam", "Meningkatkan kontraktilitas otot detrusor kandung kemih", "Menghambat reabsorpsi natrium di tubulus proksimal", "Menurunkan produksi urin pada malam hari"], "answer": 0, "topic": "Neoplasma & prostat"}, {"id": 91, "question": "Menurut standar WHO, penggunaan obat dikatakan rasional apabila memenuhi kriteria berikut, kecuali:", "options": ["Tepat indikasi dan tepat diagnosis", "Tepat pemilihan obat, dosis, cara, dan lama pemberian", "Tepat penilaian kondisi pasien dan waspada efek samping", "Selalu memilih obat merek dagang paling mahal agar efeknya terjamin", "Tersedia, terjangkau, dan disertai informasi yang jelas kepada pasien"], "answer": 3, "topic": "Peresepan rasional"}, {"id": 92, "question": "Dalam struktur penulisan resep yang lengkap dan sah secara hukum di Indonesia, bagian resep yang berisi nama obat, bentuk sediaan, kekuatan dosis, serta jumlah obat yang diminta disebut:", "options": ["Praescriptio (ordinatio)", "Inscriptio", "Invocatio", "Signatura", "Subscriptio"], "answer": 0, "topic": "Peresepan rasional"}, {"id": 93, "question": "Bagian resep yang diawali dengan huruf \"S\" dan memuat aturan pakai obat (frekuensi, dosis tiap kali minum, waktu pemberian, dan rute pemakaian) untuk dituliskan pada etiket obat adalah:", "options": ["Signatura", "Inscriptio", "Invocatio", "Praescriptio", "Subscriptio"], "answer": 0, "topic": "Peresepan rasional"}, {"id": 94, "question": "Penulisan angka Romawi pada resep standar (seperti \"No. X\" atau \"No. XV\") berfungsi untuk:", "options": ["Menyatakan jumlah satuan sediaan obat yang harus diserahkan oleh apoteker", "Menyatakan usia pasien dalam tahun", "Menyatakan nomor urut pemeriksaan pasien di poliklinik", "Menyatakan lama penyimpanan obat di lemari es", "Menyatakan jumlah kali obat boleh ditebus ulang"], "answer": 0, "topic": "Peresepan rasional"}, {"id": 95, "question": "Seorang dokter meresepkan sirup antibiotik untuk pasien anak berusia 3 tahun. Komponen identitas pasien yang wajib dicantumkan pada bagian bawah resep agar apoteker dapat memverifikasi keamanan dosis adalah:", "options": ["Nama lengkap pasien, umur, dan berat badan anak", "Pekerjaan orang tua dan pendidikan terakhir", "Nomor kartu keluarga dan golongan darah", "Riwayat imunisasi lengkap sejak lahir", "Nama dokter spesialis yang pernah dikunjungi"], "answer": 0, "topic": "Peresepan rasional"}, {"id": 96, "question": "Dalam penulisan resep yang aman dan dapat dibaca, singkatan latin \"S. 3 d.d. tab I p.c.\" memiliki arti:", "options": ["Tandai tiga kali sehari satu tablet sesudah makan", "Tandai tiga kali sehari satu tablet sebelum makan", "Tandai setiap tiga hari satu tablet saat makan", "Tandai tiga kali sehari satu sendok teh bila perlu", "Tandai tiga tetes dua kali sehari pada telinga kanan"], "answer": 0, "topic": "Peresepan rasional"}, {"id": 97, "question": "Untuk mencegah kesalahan pembacaan dosis (medication error) pada resep, kaidah penulisan satuan dan angka desimal yang benar adalah:", "options": ["Menulis \"0,5 mg\" dengan nol di depan koma dan menghindari nol di belakang koma seperti \"5,0 mg\"", "Menulis \".5 mg\" tanpa angka nol di depan titik desimal", "Menyingkat \"mikrogram\" menjadi \"ug\" atau \"u\"", "Menulis \"5.0 mg\" agar terlihat lebih tegas", "Tidak menuliskan kekuatan sediaan pada obat yang memiliki beberapa dosis"], "answer": 0, "topic": "Peresepan rasional"}, {"id": 98, "question": "Perbedaan penutup tiap item obat pada resep antara obat non-narkotika dengan obat golongan narkotika/psikotropika adalah:", "options": ["Obat biasa ditutup dengan tanda paraf dokter, sedangkan obat narkotika wajib ditutup dengan tanda tangan lengkap dokter", "Obat narkotika tidak memerlukan tanggal penulisan resep", "Obat narkotika dapat diberi tanda iter (pengulangan) hingga 3 kali", "Obat biasa wajib ditulis pada kertas resep berwarna merah", "Obat narkotika tidak perlu mencantumkan alamat lengkap pasien"], "answer": 0, "topic": "Peresepan rasional"}, {"id": 99, "question": "Seorang pasien dewasa dengan sistitis akut tanpa komplikasi diresepkan Nitrofurantoin kapsul 100 mg diminum dua kali sehari selama 5 hari. Penulisan praescriptio dan signatura yang paling lengkap dan tepat adalah:", "options": ["R/ Nitrofurantoin caps 100 mg No. X / S 2 d.d. caps I p.c.", "R/ Nitrofurantoin 100 No. 5 / S 1 × 1", "R/ Nitrofurantoin caps No. X / S u.c.", "R/ Nitrofurantoin tab 500 mg No. X / S 2 d.d. tab I a.c.", "R/ Nitrofurantoin syr fls I / S 3 d.d. cth I"], "answer": 0, "topic": "Peresepan rasional"}, {"id": 100, "question": "Langkah terakhir dalam proses peresepan rasional menurut pedoman Guide to Good Prescribing WHO setelah memilih obat dan menulis resep adalah:", "options": ["Memberikan informasi, instruksi, serta peringatan kepada pasien dan memantau (menghentikan) terapi", "Mengganti obat dengan antibiotik spektrum luas bila pasien ragu", "Menyimpan salinan resep tanpa menjelaskan efek samping obat", "Menyarankan pasien menghentikan antibiotik segera setelah gejala hilang", "Menambahkan suplemen multivitamin pada setiap resep secara rutin"], "answer": 0, "topic": "Peresepan rasional"}];
const views = ["homeView","materiView","penyakitView","giziView","kalkulatorView","quizView","referensiView"];
const pageNames = {home:"homeView",materi:"materiView",penyakit:"penyakitView",gizi:"giziView",kalkulator:"kalkulatorView",quiz:"quizView",referensi:"referensiView"};
function pageFromHash(){const key=location.hash.replace('#','').toLowerCase();return pageNames[key]||'homeView';}
function showView(id){views.forEach(v=>document.getElementById(v).classList.toggle('active',v===id));document.querySelectorAll('.side-link').forEach((b,i)=>b.classList.toggle('active',(id==='homeView'?i===0:(['materiView','penyakitView','giziView','kalkulatorView','quizView','referensiView'].indexOf(id)+1)===i)));window.scrollTo({top:0,behavior:'smooth'});}
function openPage(page){const id=pageNames[page]||'homeView';history.pushState({view:id},'',`#${page}`);showView(id);if(page==='quiz')startQuiz();}
function goHome(){if(pageFromHash()!=='homeView')history.pushState({view:'homeView'},'','#home');showView('homeView');}
window.addEventListener('popstate',()=>{showView(pageFromHash());});
window.addEventListener('DOMContentLoaded',()=>{history.replaceState({view:pageFromHash()},'',location.hash||'#home');showView(pageFromHash());startQuiz();});
function calculateBMI(){const w=parseFloat(document.getElementById('weight').value),h=parseFloat(document.getElementById('height').value),r=document.getElementById('bmiResult');if(!w||!h||w<=0||h<=0){r.innerHTML='<h3>Data belum lengkap</h3><p>Masukkan berat dan tinggi badan dengan angka yang benar.</p>';return;}const bmi=w/((h/100)**2);let c=bmi<18.5?'Berat badan kurang':bmi<23?'Normal':bmi<25?'Berat badan berlebih':bmi<30?'Obesitas I':'Obesitas II';r.innerHTML=`<span class="result-symbol">✓</span><h3>IMT: ${bmi.toFixed(2)} kg/m²</h3><p>Kategori: <strong>${c}</strong><br>Klasifikasi dewasa Asia-Pasifik.</p>`;}
function resetBMI(){document.getElementById('weight').value='';document.getElementById('height').value='';document.getElementById('bmiResult').innerHTML='<span class="result-symbol">⌗</span><h3>Hasil IMT akan muncul di sini</h3><p>Masukkan berat dan tinggi badan, lalu tekan tombol hitung.</p>';}
let activeQuestions=[],qIndex=0,correctCount=0,answered=false,quizFinished=false;
function topicRange(v){if(v==='all')return quizBank;if(v==='1')return quizBank.slice(0,20);if(v==='2')return quizBank.slice(20,40);if(v==='3')return quizBank.slice(40,60);if(v==='4')return quizBank.slice(60,75);if(v==='5')return quizBank.slice(75,90);if(v==='6')return quizBank.slice(90,100);return quizBank;}
function startQuiz(){const sel=document.getElementById('quizTopic');if(!sel)return;activeQuestions=topicRange(sel.value);qIndex=0;correctCount=0;quizFinished=false;renderQuestion();}
function renderQuestion(){if(!activeQuestions.length)return;const q=activeQuestions[qIndex];answered=false;document.getElementById('questionNumber').textContent=`SOAL ${q.id} / ${activeQuestions[activeQuestions.length-1].id}`;document.getElementById('scoreLabel').textContent=`Benar: ${correctCount}`;document.getElementById('progressBar').style.width=`${qIndex/activeQuestions.length*100}%`;document.getElementById('topicLabel').textContent=q.topic;document.getElementById('questionText').textContent=q.question;document.getElementById('feedback').textContent='';const next=document.getElementById('nextButton');next.disabled=true;next.textContent=qIndex===activeQuestions.length-1?'Lihat hasil':'Soal berikutnya →';document.getElementById('skipButton').style.display='inline-block';const box=document.getElementById('options');box.innerHTML='';q.options.forEach((label,i)=>{const b=document.createElement('button');b.type='button';b.className='option';b.textContent=`${String.fromCharCode(65+i)}. ${label}`;b.onclick=()=>chooseAnswer(i);box.appendChild(b);});}
function chooseAnswer(i){if(answered||quizFinished)return;answered=true;const q=activeQuestions[qIndex],correct=i===q.answer;const buttons=[...document.querySelectorAll('.option')];buttons.forEach((b,j)=>{b.disabled=true;if(j===q.answer)b.classList.add('correct');if(j===i&&!correct)b.classList.add('wrong');});if(correct)correctCount++;document.getElementById('scoreLabel').textContent=`Benar: ${correctCount}`;document.getElementById('feedback').textContent=correct?`Benar! Jawaban sesuai kunci dokumen: ${String.fromCharCode(65+q.answer)}.`:`Belum tepat. Kunci dokumen: ${String.fromCharCode(65+q.answer)}. ${q.options[q.answer]}.`;document.getElementById('nextButton').disabled=false;document.getElementById('skipButton').style.display='none';}
function skipQuestion(){if(qIndex<activeQuestions.length-1){qIndex++;renderQuestion();}else showQuizResult();}
function nextQuestion(){if(qIndex<activeQuestions.length-1){qIndex++;renderQuestion();}else showQuizResult();}
function showQuizResult(){quizFinished=true;document.getElementById('progressBar').style.width='100%';document.getElementById('questionNumber').textContent='SELESAI';document.getElementById('scoreLabel').textContent=`Benar: ${correctCount} / ${activeQuestions.length}`;document.getElementById('topicLabel').textContent='HASIL LATIHAN';document.getElementById('questionText').textContent=`Kamu menjawab benar ${correctCount} dari ${activeQuestions.length} soal.`;document.getElementById('options').innerHTML='';document.getElementById('feedback').textContent=`Nilai: ${Math.round(correctCount/activeQuestions.length*100)}/100. Ulangi kelompok soal untuk memperkuat pemahaman.`;const n=document.getElementById('nextButton');n.disabled=false;n.textContent='Ulangi kelompok soal';n.onclick=startQuiz;document.getElementById('skipButton').style.display='none';}
